UPDATE apartment_image
SET object_key = image_source.object_key,
    sha256 = image_source.sha256
FROM image_source
JOIN apartment ON apartment.complex_code = image_source.complex_code
WHERE apartment_image.apartment_id = apartment.id;

DO $$
DECLARE
    mapped_count BIGINT;
    migrated_count BIGINT;
BEGIN
    SELECT
        count(*),
        count(*) FILTER (
            WHERE object_key LIKE 'apartment-images/v2/%.webp'
        )
    INTO mapped_count, migrated_count
    FROM apartment_image;

    IF migrated_count <> mapped_count THEN
        RAISE EXCEPTION
            'Expected all apartment image mappings to use v2 keys, mapped %, migrated %',
            mapped_count,
            migrated_count;
    END IF;
END
$$;
